L8_1.m_Talk_KOREA = "잔치를 벌이며 떠들썩하던 이들이 조용히 바라볼 동안…"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "宴の喧騒も静まり、人々が黙々と見守る中……"
L8_1.m_Talk_ENG = "While the guests, so lively just moments ago, quiet down to watch…"
