L10_1.m_Talk_KOREA = "그 시절의 방식을 모르는 눈으로 보아도 백년가약을 청하는 자리임을 알겠더군."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "当時の作法を知らぬ某の目にも、それが百年の契りを交わす席であると分かった。"
L10_1.m_Talk_ENG = "Even to eyes unfamiliar with old customs, it's clear they are tying the knot."
