L20_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_VoiceFileName = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_IN_CUTSCENE_19"
L20_1.m_Talk_KOREA = "녹아내리는 이성을 부여잡고 통곡하며, 한때 웃고 떠들던 이들의 이빨에 찢겨 발겨져."
L20_1.m_fTalkTime = 0.03
L20_1.m_bTalkCenterFadeIn = true
L20_1.m_Talk_JPN = "溶け落ちゆく理性を繋ぎ止めて慟哭し、つい先程まで共に笑い騒いでいた者たちの歯によって引き裂かれ。"
L20_1.m_Talk_ENG = "Sanity dissolves as the laughing crowd rips and tears at each other with jagged teeth."
L20_1.m_Talk_TWN = "他們用僅存的理智放聲痛哭，被曾經歡笑的人們用牙齒撕裂。"
L20_1.m_Talk_SCN = "抓住融化的理智痛哭，被曾经欢笑喧闹的人的牙齿撕裂。"
L20_1.m_Talk_DEU = "Sanity dissolves as the laughing crowd rips and tears at each other with jagged teeth."
L20_1.m_Talk_FRA = "Sanity dissolves as the laughing crowd rips and tears at each other with jagged teeth."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP14_ACT1_INTERLUDE2@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 630
L21_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_VoiceFileName = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_IN_CUTSCENE_20"
L21_1.m_Talk_KOREA = "웃기 위해 모인 자리엔 살점과 피가 범벅이 되어 비린 비명만 바람을 타고 바삐 떠돌아."
L21_1.m_fTalkTime = 0.03
L21_1.m_bTalkCenterFadeIn = true
L21_1.m_Talk_JPN = "祝宴の場には肉片と血が混ざり合い、生臭い悲鳴のみが風に乗りこだまする。"
L21_1.m_Talk_ENG = "A gathering meant for smiles now soaked with flesh and blood. Only raw screams riding the wind."
L21_1.m_Talk_TWN = "原本歡樂的場合，只剩下血肉模糊，以及此起彼落的哀號聲。"
L21_1.m_Talk_SCN = "为了欢笑而聚集的场所，却充满了血肉模糊的景象，腥臭的惨叫随风四处飘荡。"
L21_1.m_Talk_DEU = "A gathering meant for smiles now soaked with flesh and blood. Only raw screams riding the wind."
L21_1.m_Talk_FRA = "A gathering meant for smiles now soaked with flesh and blood. Only raw screams riding the wind."
