L51_1 = "FX_CUTSCEN_NOISE"
L50_1.m_StartFXSoundName = L51_1
L51_1 = "…정확한 사망자는 집계되지 않았으나, 이는 챔버에서 창백한 달 이래 유래 없이 큰 피해일 것으로 추정됩니다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L50_1.m_bTalkCenterFadeIn = true
L51_1 = "……具体的な死亡者数は集計されていませんが、チェンバーでは青白い月以来最大の被害と推定されます。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "…Though an official death toll is still unknown, this is expected to be Chamber's worst disaster since the Pale Moon."
L50_1.m_Talk_ENG = L51_1
L51_1 = "…目前無法統計死亡人數，但這會是強巴在蒼月事件後，死傷最慘重的一次。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "…虽然确切的死亡人数尚未统计，但据推测，这是自苍白之月以来在会议室中遭受的最大损失。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "…Though an official death toll is still unknown, this is expected to be Chamber's worst disaster since the Pale Moon."
L50_1.m_Talk_DEU = L51_1
