L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "관리국은 해당 침식사태에 영향을 받은 구역에 한시적 2급 접근금지를 공표하고, 재난민들에게 적절한 조치를…"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L1_1.m_bTalkCenterFadeIn = true
L2_1 = "管理局は当該侵食事態に影響を受けた区域に対し、一時的に2級接近禁止を発表し、被害者の方々に適切な措置を……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "The Administration has declared a temporary Level-2 no-entry zone in the affected area, and is coordinating relief for evacuees…"
L1_1.m_Talk_ENG = L2_1
L2_1 = "管理局宣布受到侵蝕災難影響的區域暫時進入二級警戒，民眾不得進出，並將對受災居民提供協助…"
L1_1.m_Talk_TWN = L2_1
L2_1 = "管理局宣布对受该侵蚀事件影响的区域暂时实施二级禁入，并对灾民采取适当措施…"
L1_1.m_Talk_SCN = L2_1
L2_1 = "The Administration has declared a temporary Level-2 no-entry zone in the affected area, and is coordinating relief for evacuees…"
L1_1.m_Talk_DEU = L2_1
L2_1 = "The Administration has declared a temporary Level-2 no-entry zone in the affected area, and is coordinating relief for evacuees…"
