L4_1.m_CharStrID = L5_1
L5_1 = "…비록 육신은 함께하지 못하지만, 우린 그들을 영원히 기억할 것입니다…"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "……たとえ身体はここになくとも、我々は彼らを永遠に忘れないでしょう……"
L4_1.m_Talk_JPN = L5_1
L5_1 = "…Though their bodies are not with us, we will remember them forever…"
L4_1.m_Talk_ENG = L5_1
L5_1 = "…雖然他們的肉體已經不在世上，但我們會永遠記住他們…"
L4_1.m_Talk_TWN = L5_1
L5_1 = "…虽然肉体无法与我们同在，但我们将永远铭记他们…"
