L6_1.m_CharStrID = L7_1
L7_1 = "참 너무하지 않나? 유품 밖에 없는 텅 빈 관이라니."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "遺品しかない空っぽの棺だなんて、ひどいと思わないか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "An empty coffin with nothing but keepsakes? That's just cruel."
L6_1.m_Talk_ENG = L7_1
L7_1 = "棺材裡只有遺物而已，這會不會太過分？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "只有遗物的空棺材，真是太过分了吧？"
