L8_1 = "MOURNSERS_NPC_NULL_14"
L7_1.m_CharStrID = L8_1
L8_1 = "침식파 영향을 받은 재난사상자는 관리국이 처리하도록 되어있으니까. 이해가 안 되는 것도 아니지만 씁쓸하구만."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "侵食波の影響を受けた災害死傷者の処理は、管理局が行うらしいから……分からなくはないけど、なんとも複雑な気持ちだな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Victims of the Corruption ray have to be handled by the Administration. I get it, but still leaves a bad taste."
L7_1.m_Talk_ENG = L8_1
L8_1 = "因為受侵蝕波影響的罹難者是由管理局處理的。這也不是不能理解，但還是令人難過。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "受到侵蚀派影响的灾难伤者由管理局处理。虽然不是不能理解，但还是有些心酸。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Victims of the Corruption ray have to be handled by the Administration. I get it, but still leaves a bad taste."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Victims of the Corruption ray have to be handled by the Administration. I get it, but still leaves a bad taste."
