L13_1.m_Pos = "R"
L14_1 = "딱히 없어요. 연고라곤 저 멀리 계신 은사님 밖에 없고, 학교 안 다녀서 친구도 없거든요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ないです。知り合いなんて遠くに住んでる恩師しかいないし、学校は通ってないから友だちもいなくて。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Not really. Only person I know is my old teacher way out somewhere. Didn't go to school, so no friends either."
L13_1.m_Talk_ENG = L14_1
L14_1 = "沒了。我只有一個遠方的恩師，而且我沒有上學，所以也沒有朋友。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "没有。除了远方的恩师，我没有任何亲戚，因为我没上过学，所以也没有朋友。"
