L21_1 = "OFFICER2_NPC_NULL_14"
L20_1.m_CharStrID = L21_1
L21_1 = "먹비 속에서도 멀쩡히 살아남은 유일한 사례입니다. 쉘터에 들어간 적도 없다더군요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "墨雨を浴びて無事に生き残った唯一のケースです。シェルターに入ったこともないそうですよ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "She's the only survivor who made it through Ink Rain. She also hasn't been in a shelter."
L20_1.m_Talk_ENG = L21_1
L21_1 = "這個孩子是在墨雨中唯一倖存的案例。而且她從未進入庇護所。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "他们是墨雨中的唯一幸存者。据说他们从未进入过避难所。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "She's the only survivor who made it through Ink Rain. She also hasn't been in a shelter."
L20_1.m_Talk_DEU = L21_1
L21_1 = "She's the only survivor who made it through Ink Rain. She also hasn't been in a shelter."
