L21_1.m_CharStrID = L22_1
L22_1 = "그 아이에게 침식 면역 체계가 있을 가능성을 검증하려는 겁니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "あの子が侵食に対する免疫体系を持っている可能性を検証させていただきたいのです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "We intend to test whether she has a natural immunity to Corruption."
