L24_1.m_CharStrID = L25_1
L25_1 = "관리국의 허가는 받아뒀습니다. 면역 반응 연구가 성공한다면 최종적으로는 수많은 인명을 구하게 되겠죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "管理局の許可は得ています。免疫反応の研究が成功すれば、最終的に多くの人命を救うことになるでしょう。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "We have full Administration clearance. If we succeed, her immune response could save countless lives."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我們已經得到管理局的許可。如果免疫反應研究成功，最終將能拯救無數生命。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "我们已经获得管理局的许可。如果免疫反应研究成功，将会拯救无数生命。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "We have full Administration clearance. If we succeed, her immune response could save countless lives."
L24_1.m_Talk_DEU = L25_1
