L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "建物が崩れる時に見たリアルな走馬灯ってやつかなーと思ったら……どうやら夢じゃなかったみたいで。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "At first, I thought it was just my life flashing before my eyes as the building fell… but I don't think it was just a dream."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我本來以為是建築物倒塌時眼前閃過的跑馬燈…但我覺得那不是夢。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "我以为这只是看着建筑倒塌时的走马灯……但似乎不是梦呢。"
