L14_1 = "제가 가진 혈청인가 뭔가로 백신을 만드는 게 목표라면서요? 사람을 구하는 일이라면 당연히 도와야죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "私の血清か何かでワクチンを作るのが目標なんでしょ？　人を助けられるなら、そりゃあ協力しますよ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "If my blood can help make a vaccine, of course I'll do it. It could save people."
L13_1.m_Talk_ENG = L14_1
L14_1 = "他們是想利用我的血清來製造疫苗對吧？如果是能拯救人類的事，我當然要幫忙。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "你说要用我的血清来制造疫苗？如果是为了救人，我当然会帮忙。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "If my blood can help make a vaccine, of course I'll do it. It could save people."
