L18_1 = "ANDY_ATELIER_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "그냥, 침식사태로 온가족이 죽을 뻔한 적이 있었는데, 관리국 구조 덕분에 저만 살아남았거든요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ただ、昔……侵食事態で家族全員が死にかけたところ、管理局のおかげで私だけ助かったんです。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "My whole family almost died in a Corruption disaster. The Administration saved me."
L17_1.m_Talk_ENG = L18_1
L18_1 = "只是，我小時候因為侵蝕事態差點全家死掉，只有我幸運被管理局所救。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "只是，曾经因为侵蚀事件差点全家遇难，幸亏管理局的救援，我才活了下来。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "My whole family almost died in a Corruption disaster. The Administration saved me."
L17_1.m_Talk_DEU = L18_1
L18_1 = "My whole family almost died in a Corruption disaster. The Administration saved me."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP14_ACT1_INTERLUDE2@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 630
L18_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "ANDY_ATELIER_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "R"
L19_1 = "그래서 나도 다른 사람들에게 도움이 되고 싶다- 라는 마음은 항상 있었어요. 이번에 그 기회가 생겼을 뿐이죠."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "だから、自分も人の助けになりたいって気持ちはそれなりにあって……今回そのチャンスがやってきただけです。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "So I've always wanted to help someone else. Now I finally can."
L18_1.m_Talk_ENG = L19_1
L19_1 = "所以我一直想幫助其他人，這次剛好有這個機會。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "所以我一直都有想要帮助别人的心愿。只是刚好这次有了这样的机会而已。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "So I've always wanted to help someone else. Now I finally can."
L18_1.m_Talk_DEU = L19_1
L19_1 = "So I've always wanted to help someone else. Now I finally can."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
