L20_1 = "어린 나이에 그런 일을 겪다니. 상심이 컸겠군."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "その歳で大変な思いをしたのだな。さぞ辛かったであろう。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "To face that at your age must've left scars."
L19_1.m_Talk_ENG = L20_1
L20_1 = "這麼小的年紀就經歷這種事，打擊一定很大。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "小小年纪就经历了这样的事情，打击一定很大吧。"
