L23_1 = "C"
L22_1.m_Pos = L23_1
L23_1 = "그래도, 부모님이 살아 계셨다면 어땠을까- 하는 생각을 하면 조금 먹먹해지곤 해요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "でも、親が生きていれば今頃どうなってたんだろう……と思うと、ちょっとはへこんだりして……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Still, sometimes I wonder how things might've been if they'd survived. Can't help but feel that ache."
L22_1.m_Talk_ENG = L23_1
L23_1 = "不過，每當想到如果父母還活著會是什麼樣子…心裡就會有點難過。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "不过，有时候想象父母还在，就会有些心酸。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Still, sometimes I wonder how things might've been if they'd survived. Can't help but feel that ache."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Still, sometimes I wonder how things might've been if they'd survived. Can't help but feel that ache."
