L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 630
L44_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
