L45_1 = "RESEARCHER_NPC_NULL_AB"
L44_1.m_CharStrID = L45_1
L45_1 = "L"
L44_1.m_Pos = L45_1
L45_1 = "연구에 전혀 진전이 없어요. 침식에 대한 항체 반응이 전혀 없더라고요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "研究はまったく進展していません。侵食に対する抗体反応がまるで見られないのです。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "We've made no headway. There's no sign of any antibodies."
L44_1.m_Talk_ENG = L45_1
L45_1 = "研究完全沒有進展。我發現她身上完全沒有對侵蝕的抗體反應。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "研究完全没有进展。对侵蚀的抗体反应完全没有效果。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "We've made no headway. There's no sign of any antibodies."
L44_1.m_Talk_DEU = L45_1
L45_1 = "We've made no headway. There's no sign of any antibodies."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP14_ACT1_INTERLUDE2@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 630
L45_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "SEOSAENG_ATELIER_NULL_BLADE"
L45_1.m_Pos = "R"
L46_1 = "그 아이가 살아남은 게 순전한 우연일 수도 있단 말인가?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あの子が生き残ったのは、ただの偶然である可能性もあるということか？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "So the girl surviving was pure chance?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "那孩子能活下來，難道純粹是個巧合嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "所以说那个孩子能活下来可能纯属偶然是吗？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "So the girl surviving was pure chance?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "So the girl surviving was pure chance?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP14_ACT1_INTERLUDE2@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 630
L46_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "RESEARCHER_NPC_NULL_AB"
L46_1.m_CharStrID = L47_1
L47_1 = "L"
L46_1.m_Pos = L47_1
L47_1 = "기적일 지도 모르죠. 아니면 쉘터에 안전하게 숨어있다가 나와서 저희한테 거짓말한 걸 수도 있고요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "奇跡かもしれませんね。でなければ、シェルターに隠れていたのにそうでないと嘘をついたのかもしれませんし。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Might've been a miracle. Or maybe she hid in a shelter and lied."
L46_1.m_Talk_ENG = L47_1
L47_1 = "或許是奇蹟吧。或者她躲在庇護所裡，然後出來騙我們。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "也许是奇迹吧。或者是在避难所里安全地躲藏着，然后出来对我们撒谎。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Might've been a miracle. Or maybe she hid in a shelter and lied."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Might've been a miracle. Or maybe she hid in a shelter and lied."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP14_ACT1_INTERLUDE2@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 630
L47_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L47_1.m_bWaitClick = true
