L48_1 = "UNIT_DESPAIR"
L47_1.m_Face = L48_1
L47_1.m_CharStrID = "SEOSAENG_ATELIER_NULL_BLADE"
L47_1.m_Pos = "R"
L48_1 = "앤디는… 그 정도로 계획적인 성격은 아닐세."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "アンディーは……それほど計画的な性格ではない。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Andy's… not that calculated."
L47_1.m_Talk_ENG = L48_1
L48_1 = "安狄…不是城府那麼深的人。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "安迪……并不是那么有计划性的人。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Andy's… not that calculated."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Andy's… not that calculated."
L47_1.m_Talk_FRA = L48_1
