L49_1 = "EP14_ACT1_INTERLUDE2@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 630
L48_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "RESEARCHER_NPC_NULL_AB"
L48_1.m_CharStrID = L49_1
L49_1 = "L"
L48_1.m_Pos = L49_1
L49_1 = "아무튼 전 슬슬 이 프로젝트에 회의감이 들어요. 텅 빈 호수에서 보물 찾는 기분이랄까요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "とにかく、私はもうこのプロジェクトに対して確信がないんです。空っぽの湖で宝探しをしているような気分とでも言いましょうか。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I'm losing faith in this project. Feels like digging for treasure in an empty lake."
L48_1.m_Talk_ENG = L49_1
L49_1 = "總之，我開始對這個專案感到懷疑，感覺像是大海裡撈針一樣。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "总之，我开始怀疑这个项目了。就像是在空荡荡的湖里寻找宝物的感觉吧。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "I'm losing faith in this project. Feels like digging for treasure in an empty lake."
L48_1.m_Talk_DEU = L49_1
L49_1 = "I'm losing faith in this project. Feels like digging for treasure in an empty lake."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
