L50_1 = "RESEARCHER_NPC_NULL_AB"
L49_1.m_CharStrID = L50_1
L50_1 = "L"
L49_1.m_Pos = L50_1
L50_1 = "차라리 요즘 떠도는 시간 여행에 대해 조사하는 편이 재밌을 것 같습니다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "いっそのこと、最近話題のタイムトラベルについて調査したほうが面白そうなくらいです。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Might be more fun to look into all these time travel rumors instead."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我寧願去調查最近流傳的時間旅行會更有趣。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "倒不如去调查最近流行的时间旅行会更有趣。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Might be more fun to look into all these time travel rumors instead."
L49_1.m_Talk_DEU = L50_1
