L11_1 = "C"
L10_1.m_Pos = L11_1
L11_1 = "건물이 무너지면서 보는 생생한 주마등 같은 거라 생각했는데… 아무래도 꿈이 아닌 것 같더라구요."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "建物が崩れる時に見たリアルな走馬灯ってやつかなーと思ったら……どうやら夢じゃなかったみたいで。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "At first, I thought it was just my life flashing before my eyes as the building fell… but I don't think it was just a dream."
L10_1.m_Talk_ENG = L11_1
L11_1 = "我本來以為是建築物倒塌時眼前閃過的跑馬燈…但我覺得那不是夢。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "我以为这只是看着建筑倒塌时的幻影……但似乎不是梦呢。"
