L15_1 = "CUTSCENE_TALK_04"
L14_1.m_StartBGMFileName = L15_1
L15_1 = "챔버는 관리국의 돌봄 아래 있는 대도시지만, 그럼에도 제법 많은 침식현상을 겪었어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "チェンバーは管理局の保護下にある大都市であるが、かなりの侵食現象を経験している。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Chamber's under Administration care, yet it's seen plenty of Counterside Effects."
L14_1.m_Talk_ENG = L15_1
L15_1 = "強巴雖然是個在管理局庇護下的大都市，但也經歷過相當多的侵蝕現象。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "会议室是一个在管理局管理的大都市，但即便如此，也经历了许多侵蚀现象。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Chamber's under Administration care, yet it's seen plenty of Counterside Effects."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Chamber's under Administration care, yet it's seen plenty of Counterside Effects."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP14_ACT1_INTERLUDE2@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 630
L15_1.m_CutScenStrID = "EP14_ACT1_INTERLUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "허나 먹비라 불리는 괴현상에 휘말린 것은 이번이 처음이더군."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "しかし墨雨と呼ばれる怪奇現象に巻き込まれたのは今回が初めてのようだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "But this Ink Rain was a first."
L15_1.m_Talk_ENG = L16_1
L16_1 = "然而，這是第一次捲入被稱為墨雨的怪異現象。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "不过这还是我第一次被卷入所谓的墨雨现象中。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "But this Ink Rain was a first."
L15_1.m_Talk_DEU = L16_1
L16_1 = "But this Ink Rain was a first."
L15_1.m_Talk_FRA = L16_1
